3	/**
4	 * The Luhn check digit (0-9) computed over the digits contained in an owner's customer code.
5	 * Non-digit characters (the hyphens) are ignored; the standard Luhn algorithm doubles every
6	 * second digit from the right and reduces the running sum modulo ten.
7	 */
8	public final class CheckDigit {
9	
10	    private CheckDigit() {
11	    }
12	
13	    public static Integer of(String customerCode) {
14	        if (customerCode == null) {
15	            return null;
16	        }
17	        int sum = 0;
18	        boolean dbl = true;
19	        for (int i = customerCode.length() - 1; i >= 0; i--) {
20	            char c = customerCode.charAt(i);
21	            if (c < '0' || c > '9') {
22	                continue;
23	            }
24	            int d = c - '0';
25	            if (dbl) {
26	                d *= 2;
27	                if (d > 9) {
28	                    d -= 9;
29	                }
30	            }
31	            sum += d;
32	            dbl = !dbl;
33	        }
34	        return (10 - (sum % 10)) % 10;
35	    }
36	}
